use gielinor_client::{disk_cache::DiskCache,animation::Skeleton};
use std::io::Write;
fn records(out:&mut std::fs::File,records:Vec<(u32,Vec<u8>)>)->std::io::Result<()>{out.write_all(&(records.len() as u32).to_be_bytes())?;for(id,data)in records{out.write_all(&id.to_be_bytes())?;out.write_all(&(data.len() as u32).to_be_bytes())?;out.write_all(&data)?;}Ok(())}
fn main()->Result<(),Box<dyn std::error::Error>>{let a=std::env::args().collect::<Vec<_>>();let mut c=DiskCache::open(&a[1],64<<20)?;let mut out=std::fs::File::create(&a[2])?;records(&mut out,c.group(2,12,[0;4])?.into_iter().filter(|(id,_)|id%23==0).collect())?;let ids=c.reference(1)?.groups.iter().map(|g|g.id).collect::<Vec<_>>();let mut skeletons=Vec::new();for id in ids{let data=c.file(1,id,0,[0;4])?;if Skeleton::decode(id as u16,&data).is_ok(){skeletons.push((id,data));}}records(&mut out,skeletons)?;let ids=c.reference(0)?.groups.iter().map(|g|g.id).filter(|id|id%47==0).collect::<Vec<_>>();let mut frames=Vec::new();for id in ids{for(file,data)in c.group(0,id,[0;4])?.into_iter().take(2){if data[..2]!=1941u16.to_be_bytes(){frames.push((id<<16|file,data));}}}records(&mut out,frames)?;Ok(())}
